import{_ as t,o as i,c as n,aa as o}from"./chunks/framework.BAs_AphD.js";const a="/buildary-help-preview/media/en/tickets/offline.png",s="/buildary-help-preview/media/en/tickets/offline_2.png",r="/buildary-help-preview/media/en/tickets/offline_wifi.png",y=JSON.parse('{"title":"Offline mode","description":"","frontmatter":{"title":"Offline mode","wiki":"en:tickets:m_offline"},"headers":[],"relativePath":"en/tickets/m_offline.md","filePath":"en/tickets/m_offline.md","lastUpdated":1794388980000}'),l={name:"en/tickets/m_offline.md"};function c(d,e,f,h,p,m){return i(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="offline-mode" tabindex="-1">Offline mode <a class="header-anchor" href="#offline-mode" aria-label="Permalink to &quot;Offline mode&quot;">​</a></h1><p>Offline mode is typically used when the construction site lacks sufficiently reliable data services.</p><p>After switching to offline mode, you can create new tasks or edit existing ones. All changes are saved to your mobile device. Once you have a sufficiently strong internet connection, you can synchronize the data with the server. The changes you made will be saved to the server, and any changes made by other users since your last synchronization will be transferred from the server to your device.</p><figure class="shot" style="--w:600px;"><img src="'+a+'" alt="" width="400" loading="lazy"></figure><p>Working in offline mode has certain advantages and disadvantages. One advantage is the independence from data connectivity and the increased speed of work. The disadvantage is outdated information and the possibility of conflicts if multiple users make changes to the same task at the same time.</p><p>You switch to Offline mode by selecting <strong>Work Offline.</strong></p><p>To switch back to <strong>Online</strong> mode, select the opposite option.</p><p>The indicator in the application header shows that you are in Offline mode.</p><figure class="shot" style="--w:600px;"><img src="'+s+'" alt="" width="400" loading="lazy"></figure><p>When switching from Offline to Online, locally stored data and server data need to be synchronized. Synchronization starts automatically upon entering the construction site.</p><h2 id="synchronization" tabindex="-1">Synchronization <a class="header-anchor" href="#synchronization" aria-label="Permalink to &quot;Synchronization&quot;">​</a></h2><figure class="shot" style="--w:600px;"><img src="'+r+'" alt="" width="400" loading="lazy"></figure><p>A red crossed Wi-Fi icon signifies tasks that have not yet been synchronized with the server. This means that newly created tasks are visible only on your mobile device and are not available anywhere else.</p><p>You can initiate synchronization from the menu in the top left corner by selecting &quot;Choose project.&quot; Selecting a construction site will start the synchronization.</p><p>After a successful synchronization, the red crossed-out Wi-Fi icon will disappear.</p>',15)])])}const g=t(l,[["render",c]]);export{y as __pageData,g as default};
